window.IrisShaders = {
"vs": "\n        #version 300 es\n        in vec4 position;\n        void main() { gl_Position = position; }\n    ",
"fs-bake": "\n        #version 300 es\n        precision highp float;\n        layout(location = 0) out vec4 T0;\n        layout(location = 1) out vec4 T1;\n        layout(location = 2) out vec4 T2;   // pheo | yellow | gap melanin | gap stroma (per texel material)\n        layout(location = 3) out vec4 T3;   // §21 E1: occlusion | stroma thickness | top-layer coverage | 1\n\n        uniform vec2  u_size;\n        uniform float u_seed;\n        // genome\n        uniform float g_cellsCoarse, g_cellsMed, g_stretchCoarse, g_stretchMed, g_warpAmp;\n        uniform float g_radialFurrows, g_fieldWeight, g_furrowDepth, g_strandGain;\n        // explicit objects (study/00 §9.1): row 0 header + collarette harmonics, row 1 crypts,\n        // row 2 furrows, row 3 spots, row 4 nodules. Bundles come pre-rasterised in u_bundles.\n        uniform sampler2D u_objs;\n        uniform sampler2D u_bundles;\n        // study/08 S1: the curves variant of this shader is compiled separately (bakeCurvesProgram fills the two STRAND markers),\n        // so the LIC shader's code — and its float arithmetic — stays exactly v83's\n        //STRAND_DECL//\n        uniform sampler2D u_splats;      // §19.5: the fitted relief field (r, mm), additive Gaussians\n        uniform sampler2D u_paint;       // §20 D2: painted material deltas (Δmelanin, Δstroma, Δyellow, Δpheo)\n        uniform float g_rimSharp;        // 0 soft openings … 1 hard rims\n        uniform float g_openWarp;        // mm of strand displacement per unit field gradient around openings\n        uniform float g_openDepth;       // depth gain of openings over the fitted field\n        // §22 F0: the strand contrast controls the spectrum diagnostic measures. `strandMed` / `strandFine`\n        // are the weights of the 0.16 mm and 0.055 mm scales against the 0.5 mm bundles (defaults 0.28 /\n        // 0.17 reproduce v62 exactly); `strandSharp` narrows the coverage transfer of every scale, most\n        // at the fine one, which is what puts energy in the 30–90 µm band instead of smearing it.\n        uniform float g_strandMed, g_strandFine, g_strandSharp;\n        uniform float u_licSteps;        // quality: LIC step budget (12 = normal); the integration length stays the same\n        uniform float u_layers;          // §21 E1: strand layers (1 draft, 2 normal, 3 fine+)\n        // control fields (study/07 §1), packed RGBA8, decoded with the ranges injected from FIELD_DEFS\n        uniform sampler2D u_c0, u_c1, u_c2, u_f0, u_f1, u_f2;\n        //FIELD_DECODE//\n        #define OBJ(i, row) texelFetch(u_objs, ivec2(i, row), 0)\n        float wrapDiff(float a, float b) { float d = a - b; return d - floor(d + 0.5); }   // shortest angular difference in turns\n        float rMM(float v) { return 2.0 + 4.0 * v; }                                       // mm from the pupil centre at reference dilation\n        uniform float g_melanin, g_stroma, g_fibreContrast, g_cloud;\n        uniform float g_limbalWidth, g_limbalDark, g_pupZoneMel;\n\n        #define PI 3.14159265359\n\n        // ---- periodic lattice noise (x wraps mod N) ----\n        float hash21(vec2 p) {\n            vec3 p3 = fract(vec3(p.xyx) * .1031);\n            p3 += dot(p3, p3.yzx + 33.33);\n            return fract((p3.x + p3.y) * p3.z);\n        }\n        vec2 hash22(vec2 p) {\n            vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));\n            p3 += dot(p3, p3.yxz + 33.33);\n            return fract((p3.xx + p3.yz) * p3.zy);\n        }\n        // value noise on a lattice of N cells around the circle, M cells across v, offset by seed\n        float pnoise(vec2 uv, float N, float M, float s) {\n            vec2 p = vec2(uv.x * N, uv.y * M);\n            vec2 i = floor(p), f = fract(p);\n            f = f * f * (3.0 - 2.0 * f);\n            vec2 i0 = vec2(mod(i.x, N), i.y) + s;\n            vec2 i1 = vec2(mod(i.x + 1.0, N), i.y) + s;\n            float a = hash21(i0), b = hash21(i1);\n            float c = hash21(i0 + vec2(0.0, 1.0)), d = hash21(i1 + vec2(0.0, 1.0));\n            return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);\n        }\n        float pfbm(vec2 uv, float N, float M, float s) {\n            float v = 0.0, a = 0.5;\n            for (int i = 0; i < 5; i++) {\n                v += a * pnoise(uv, N, M, s + float(i) * 17.0);\n                N *= 2.0; M *= 2.0; a *= 0.5;\n            }\n            return v;\n        }\n        // periodic Worley: returns F1, F2, cell hash. N cells around the circle, M cells across the\n        // annulus. With the annulus ≈ 4 mm and the mid radius ≈ 4 mm, a cell is 25/N mm wide and 4/M mm\n        // tall, so M = 0.16 N / stretch makes cells `stretch` times taller than wide (radial bundles).\n        vec3 worley(vec2 uv, float N, float M, float s) {\n            vec2 p = vec2(uv.x * N, uv.y * M);\n            vec2 ip = floor(p), fp = fract(p);\n            float f1 = 8.0, f2 = 8.0, id = 0.0;\n            for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n                vec2 g = vec2(float(i), float(j));\n                vec2 cell = ip + g; cell.x = mod(cell.x, N);\n                vec2 o = hash22(cell + s);\n                float d = length(g + o - fp);\n                if (d < f1) { f2 = f1; f1 = d; id = hash21(cell + s + 3.0); }\n                else if (d < f2) f2 = d;\n            }\n            return vec3(f1, f2, id);\n        }\n\n        // Fuchs crypts: for every kept cell in the 3x3 neighbourhood, a soft radially elongated lens\n        // around its feature point. Not clipped by the Voronoi polygon, so the shapes stay smooth.\n        float cryptField(vec2 uv, float N, float M, float prob, float size, float s) {\n            vec2 p = vec2(uv.x * N, uv.y * M);\n            vec2 ip = floor(p), fp = fract(p);\n            float c = 0.0;\n            for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n                vec2 g = vec2(float(i), float(j));\n                vec2 cell = ip + g; cell.x = mod(cell.x, N);\n                float id = hash21(cell + s + 3.0);\n                if (id > prob) continue;\n                vec2 o = hash22(cell + s);\n                vec2 d = (g + o - fp);\n                d.x *= 1.0 + 0.6 * (hash21(cell + s + 9.0) - 0.5);        // per-crypt aspect\n                float sz = size * (0.7 + 0.6 * hash21(cell + s + 5.0));\n                float r = length(d) / sz;\n                c = max(c, smoothstep(0.55, 0.25, r));\n            }\n            return c;\n        }\n\n        // ---- strand generator (study/07 §2): line integral convolution along the flow field ----\n        // 3-D value noise on the circle embedding: periodic in angle by construction, across-strand\n        // wavelength = spacing (mm), along-strand wavelength ≈ 5 × spacing\n        float hash13(vec3 p) { p = fract(p * 0.1031); p += dot(p, p.zyx + 31.32); return fract((p.x + p.y) * p.z); }\n        float vnoise3(vec3 p) {\n            vec3 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);\n            return mix(mix(mix(hash13(i), hash13(i + vec3(1,0,0)), f.x), mix(hash13(i + vec3(0,1,0)), hash13(i + vec3(1,1,0)), f.x), f.y),\n                       mix(mix(hash13(i + vec3(0,0,1)), hash13(i + vec3(1,0,1)), f.x), mix(hash13(i + vec3(0,1,1)), hash13(i + vec3(1,1,1)), f.x), f.y), f.z);\n        }\n        float strandNoise(vec2 uv, float spacing, float phase, vec2 warpMM, float s) {\n            float r = rMM(uv.y);\n            // position in mm along the circle, warped, then wrapped onto the circle embedding\n            float aMM = uv.x * 6.2831853 * r + warpMM.x + phase / 6.2831853 * spacing;\n            float vMM = uv.y * 4.0 + warpMM.y;\n            float R = r / spacing;                                                 // circle radius in strand units\n            float ang = aMM / r;\n            vec3 p = vec3(cos(ang) * R, sin(ang) * R, vMM / (spacing * 5.0));\n            return 0.65 * vnoise3(p + s) + 0.35 * vnoise3(p * 2.03 + s + 7.0);\n        }\n        // flow direction at uv: angle from radial (+v), from the flow field\n        float flowAt(vec2 uv) { return FD(texture(u_f0, uv).r, R_flowDir); }\n        float lic(vec2 uv, float spacing, float phase, vec2 warpMM, float s, int baseSteps, float dsMul) {\n            float acc = 0.0, wsum = 0.0;\n            int steps = int(float(baseSteps) * u_licSteps / 12.0 + 0.5);            // quality scales the step count …\n            float ds = dsMul * spacing * float(baseSteps) / float(steps);           // … at a constant integration length\n            for (int dir = -1; dir <= 1; dir += 2) {\n                vec2 p = uv;\n                for (int k = 0; k < 40; k++) {\n                    if (k >= steps) break;\n                    float th = flowAt(p);\n                    vec2 dmm = vec2(sin(th), cos(th)) * float(dir) * ds;         // (across, along) in mm\n                    p += vec2(dmm.x / (6.2831853 * rMM(p.y)), dmm.y / 4.0);\n                    float w = 1.0 - float(k) / (float(steps) + 1.0);\n                    acc += w * strandNoise(p, spacing, phase, warpMM, s); wsum += w;\n                }\n            }\n            acc += strandNoise(uv, spacing, phase, warpMM, s); wsum += 1.0;\n            return acc / wsum;\n        }\n\n        // ---- F2 (spec §24): a phase-addressable strand carrier, Gabor-noise style. Every flow cell carries its own\n        // plane wave cos(2π·x'/spacing + phase), x' measured across that cell's flow from that cell's centre, and the\n        // four nearest cells' waves are blended bilinearly. Local coordinates matter: an x' measured from u = 0 has a\n        // lever arm of up to 25 mm, so the 0.008 rad step of a u8 flow angle moves a stripe by four periods (v72 debug).\n        // fit.js demodulates the photograph in exactly these per-cell frames, so the fitted (spacing, phase) put each\n        // strand where the photo's is. Value noise has no such phase: shifting it re-rolls the pattern.\n        float strandCarrier(vec2 uv, float s) {\n            ivec2 gs = textureSize(u_f2, 0);                     // the placement grid (§25: fixed in mm, independent of the flow grid)\n            vec2 gp = uv * vec2(gs) - 0.5;\n            ivec2 g0 = ivec2(floor(gp));\n            vec2 t = gp - vec2(g0);\n            float r = rMM(uv.y), acc = 0.0;\n            for (int dj = 0; dj <= 1; dj++) for (int di = 0; di <= 1; di++) {\n                float wgt = (di == 1 ? t.x : 1.0 - t.x) * (dj == 1 ? t.y : 1.0 - t.y);\n                if (wgt <= 0.0) continue;\n                ivec2 c = ivec2((g0.x + di + gs.x) % gs.x, clamp(g0.y + dj, 0, gs.y - 1));\n                vec2 cc = (vec2(c) + 0.5) / vec2(gs);\n                vec4 f2c = texelFetch(u_f2, c, 0);\n                // the flow angle at the placement cell's centre, bilinear on the flow grid (a texel centre when the two\n                // grids agree, a 2×2 mean at FINE and above) — fit.js demodulates in exactly this frame\n                float th = FD(texture(u_f0, cc).r, R_flowDir), sp = FD(f2c.g, R_placeSpacing);\n                float ph = atan(FD(f2c.a, R_phaseS), FD(f2c.b, R_phaseC));\n                float da = wrapDiff(uv.x, cc.x) * 6.2831853 * r, dv = (uv.y - cc.y) * 4.0;   // mm from the cell centre\n                acc += wgt * cos(6.2831853 * (da * cos(th) - dv * sin(th)) / sp + ph);\n            }\n            float m = vnoise3(vec3(uv.x * 6.2831853 * r / 0.11, uv.y * 4.0 / 0.33, s));   // strands swell and break\n            return clamp(0.5 + 0.5 * acc * (0.55 + 0.45 * m), 0.0, 1.0);\n        }\n\n        void main() {\n            vec2 uv = gl_FragCoord.xy / u_size;           // u angle, v tissue\n            float u = uv.x, v = uv.y, s = u_seed;\n\n            // ---- fields ----\n            vec2 warp = g_warpAmp * vec2(pfbm(uv, 6.0, 3.0, s + 1.0) - 0.5, pfbm(uv, 6.0, 3.0, s + 8.0) - 0.5);\n            vec2 w = uv + warp;\n            w.x += 0.004 * (pnoise(vec2(0.0, v), 1.0, 6.0, s + 2.0) - 0.5);   // slight angular shear\n            vec3 wa = worley(w, g_cellsCoarse, 0.16 * g_cellsCoarse / g_stretchCoarse, s + 10.0);\n            vec3 wb = worley(w + vec2(0.011, 0.0), g_cellsMed, 0.16 * g_cellsMed / g_stretchMed, s + 11.0);\n            float fa = 1.0 - smoothstep(0.05, 0.42, wa.y - wa.x);    // coarse bundles along cell edges\n            float fb = 1.0 - smoothstep(0.05, 0.35, wb.y - wb.x);    // medium mesh\n            float grain = pfbm(uv, 400.0, 40.0, s + 3.0);             // fine directional grain\n            float field = clamp(max(fa, 0.7 * fb) * (0.45 + 0.55 * grain), 0.0, 1.0);\n            vec4 bnd = texture(u_bundles, uv);                          // explicit bundles: r brightness, g height\n            // ---- strands: LIC along the flow field ----\n            vec4 f0 = texture(u_f0, uv), f1 = texture(u_f1, uv), f2 = texture(u_f2, uv);\n            float spacing = FD(f0.a, R_spacing), fCoh = FD(f1.g, R_coherence), fBright = FD(f1.b, R_strandBright);\n            float fPlace = FD(f2.r, R_place);                                  // F2: carrier weight (its spacing and phase are fetched per cell)\n            // (the noise scales keep reading `spacing`: a lattice whose scale varies per texel slides and decorrelates,\n            // and leaving that path alone keeps every unplaced iris bit-identical)\n            vec2 warpMM = vec2(FD(f0.g, R_warpU), FD(f0.b, R_warpV));\n            {   // openings push the strands aside (§19.6 f): displace the strand sampling toward the opening's\n                // centre by g_openWarp × ∇field, so the pattern outside is the pattern from further in — the\n                // bundles bend around the hole instead of running through it. Gradient by 4 taps ≈ 0.1 mm apart.\n                float rr = rMM(v), duu = 0.1 / (6.2831853 * rr), dvv = 0.1 / 4.0;\n                float gx = (texture(u_splats, uv + vec2(duu, 0.0)).r - texture(u_splats, uv - vec2(duu, 0.0)).r) / 0.2;\n                float gy = (texture(u_splats, uv + vec2(0.0, dvv)).r - texture(u_splats, uv - vec2(0.0, dvv)).r) / 0.2;\n                warpMM -= g_openWarp * vec2(gx, gy);\n            }\n            // hierarchical strands (07 §2, corrected by the polar A/B on ref 25): most of the contrast sits\n            // in 0.3–1 mm bundles with soft edges; medium and fine strands ride on top with less weight\n            // integration capped (§19 Phase B): coarse ±0.5 mm, medium ±0.3 mm, fine ±0.27 mm — no radial strips\n            // ---- strand layers (§21 E1): each layer is its own LIC strand set (seed and phase offset); a lower\n            // layer is visible only where the layers above are open (product of the complements), sits deeper,\n            // and receives less light. `ridge` = total visible coverage (the two-material mix), `coarse` = the top layer's bundles\n            int nLayers = int(u_layers + 0.5);\n            float ridge = 0.0, coarse = 0.0, medium = 0.0, fine = 0.0, openAbove = 1.0, hLayers = 0.0, occL = 0.0;\n            const float LAYER_DZ = 0.04;                                   // mm between strand layers\n            for (int L = 0; L < 3; L++) {\n                if (L >= nLayers) break;\n                float sl = s + 17.0 * float(L), ph = 1.7 * float(L);\n                float licC = lic(uv, spacing * 9.0, ph, warpMM, sl + 1.0, 10, 0.1);    // bundles ≈ 0.5 mm wide\n                float licM = lic(uv, spacing * 3.0, ph, warpMM, sl + 2.0, 12, 0.15);   // ≈ 0.16 mm\n                float licF = lic(uv, spacing, ph, warpMM, sl, 14, 0.35);               // ≈ 0.055 mm\n                float nCoh = strandNoise(uv + vec2(0.31, 0.0), spacing, ph, warpMM, sl + 5.0);\n                licF = mix(nCoh, licF, fCoh);\n                if (L == 0 && fPlace > 0.002) licF = mix(licF, strandCarrier(uv, s + 23.0), fPlace);   // F2\n                float seg = 0.4 + 0.6 * smoothstep(0.3, 0.7, pnoise(vec2(u, v), 24.0, 5.0, sl + 9.0));\n                // transfer half-widths: v62 was (0.20, 0.21, 0.22) around 0.50 / 0.51 / 0.52.\n                // g_strandSharp = 0 reproduces that; 1 narrows the fine scale to ≈ 0.04 (near-binary strands)\n                float sh = clamp(g_strandSharp, 0.0, 1.0);\n                float swC = 0.20 * mix(1.0, 0.45, sh), swM = 0.21 * mix(1.0, 0.30, sh), swF = 0.22 * mix(1.0, 0.18, sh);\n                float cC = smoothstep(0.50 - swC, 0.50 + swC, (licC - 0.5) * g_strandGain * 1.1 + 0.5) * seg;\n                float cM = smoothstep(0.51 - swM, 0.51 + swM, (licM - 0.5) * g_strandGain + 0.5);\n                float cF = smoothstep(0.52 - swF, 0.52 + swF, (licF - 0.5) * g_strandGain + 0.5);\n                //STRAND_FINE//\n                float wM = g_strandMed, wF = g_strandFine, wC = max(0.10, 1.0 - wM - wF);\n                float cov = clamp((wC * cC + wM * cM + wF * cF) / (wC + wM + wF), 0.0, 1.0);\n                float vis = cov * openAbove;                                   // what this layer shows\n                if (L == 0) { coarse = cC; medium = cM; fine = cF; }\n                ridge += vis; hLayers += vis * (0.5 - LAYER_DZ / 0.035 * float(L)); occL += vis * (1.0 - 0.35 * float(L));\n                openAbove *= (1.0 - cov);\n            }\n            float gapFrac = clamp(1.0 - ridge, 0.0, 1.0);\n            hLayers += gapFrac * (-0.5 - 0.6 * LAYER_DZ / 0.035 * float(nLayers - 1));   // the floor lies under the deepest layer\n            occL += gapFrac * 0.5;\n            // ---- relief field (§19.5): openings in the lattice. Negative field = the tissue opens: the\n            // strands part (coverage → 0), the rim is where the field crosses −kRim, the floor is deepened\n            // by a power law so walls are steep and floors flat when g_rimSharp is high\n            float spF = texture(u_splats, uv).r;\n            // what is a hole is fixed (deeper than kOpen); rimSharp sets the wall width (the field span over\n            // which the tissue opens). The floor keeps 15 % of the fibres and is darkened by shading, not by a fill.\n            const float kOpen = 0.012;\n            float wall = mix(0.06, 0.015, g_rimSharp);\n            float openMask = smoothstep(kOpen, kOpen + wall, -spF);\n            ridge *= 1.0 - 0.85 * openMask;\n            occL *= 1.0 - 0.6 * smoothstep(0.0, 0.08, max(0.0, -spF - kOpen) * g_openDepth);   // openings: the floor sees a cone of sky (analytic AO)\n            float thickL = clamp(0.55 + 0.45 * ridge, 0.2, 1.0) * (1.0 - 0.5 * openMask);       // stroma thickness: bundles thick, gaps and openings thin\n            ridge = clamp(ridge + 0.9 * bnd.r * coarse, 0.0, 1.0);                                       // bundle objects brighten where a coarse band already is\n            ridge = smoothstep(0.14, 1.0, ridge);                                                        // the lowest ~15 % of the coverage is true gap (06: dark fraction 12–14 %)\n            ridge *= 1.0 - 0.85 * g_limbalDark * smoothstep(1.0 - g_limbalWidth, 1.0, v);              // the limbal band darkens the strands\n            float fibres = clamp(max(ridge, g_fieldWeight * field), 0.0, 1.0);\n            float cloud = pfbm(uv, 5.0, 2.0, s + 4.0);                // ocularist's cloudy layer\n\n            // ---- collarette: Fourier series of radius vs angle ----\n            vec4 hdr0 = OBJ(0, 0), hdr1 = OBJ(1, 0);\n            int nCrypt = int(hdr0.x), nFurrow = int(hdr0.y), nSpot = int(hdr0.z), nNodule = int(hdr0.w);\n            int nHarm = int(hdr1.x); float collR = hdr1.y, collHeight = hdr1.z, collWidth = hdr1.w;\n            float vc = collR;\n            for (int k = 0; k < 40; k++) {\n                if (k >= nHarm) break;\n                vec4 c = OBJ(2 + k / 2, 0);\n                vec2 ab = (k % 2 == 0) ? c.xy : c.zw;\n                float ang = 6.2831853 * float(k + 1) * u;\n                vc += ab.x * cos(ang) + ab.y * sin(ang);\n            }\n            float collMask = exp(-pow((v - vc) / collWidth, 2.0));\n            // ---- control fields at this texel ----\n            vec4 c0 = texture(u_c0, uv), c1 = texture(u_c1, uv), c2 = texture(u_c2, uv);\n            float fMelanin = FD(c0.r, R_melanin), fYellow = FD(c0.g, R_yellow), fPheo = FD(c0.b, R_pheo), fStroma = FD(c0.a, R_stroma);\n            float fGapMel = FD(c1.r, R_gapMelanin), fGapStroma = FD(c1.g, R_gapStroma), fHeight = FD(c1.b, R_height), fCrypt = FD(c1.a, R_crypt);\n            {   // painted colour stamps: material deltas, so a dab mixes like pigment in the KM model\n                vec4 pd = texture(u_paint, uv);\n                fMelanin = max(0.0, fMelanin + pd.r); fGapMel = max(0.0, fGapMel + pd.r);\n                fStroma = clamp(fStroma + pd.g, 0.01, 0.5); fGapStroma = clamp(fGapStroma + 0.35 * pd.g, 0.005, 0.5);\n                fYellow = max(0.0, fYellow + pd.b); fPheo = clamp(fPheo + pd.a, 0.0, 1.0);\n            }\n            float fFurrow = FD(c2.r, R_furrow), fRadialF = FD(c2.g, R_radialFurrow), fColl = FD(c2.b, R_collarette);\n            collMask *= fColl;\n            float pupZone = 1.0 - smoothstep(vc - 0.03, vc + 0.03, v);\n\n            // radial furrows (pupillary zone): thin lines, slightly sheared\n            float rfn = pnoise(vec2(u + 0.02 * (pnoise(vec2(u, 0.0), 9.0, 1.0, s + 7.0) - 0.5), v), 180.0, 2.0, s + 12.0);\n            float radialF = pow(1.0 - abs(rfn * 2.0 - 1.0), 6.0) * pupZone * g_radialFurrows * fRadialF;\n\n            // ---- Fuchs crypts: explicit lenses (centre, size mm, radial aspect, tilt, depth, softness) ----\n            float crypt = 0.0, cryptDepth = 0.0;\n            for (int i = 0; i < 128; i++) {\n                if (i >= nCrypt) break;\n                vec4 c0 = OBJ(2 * i, 1), c1 = OBJ(2 * i + 1, 1);\n                float dx = wrapDiff(u, c0.x) * 6.2831853 * rMM(c0.y);       // mm, tangential\n                float dy = (v - c0.y) * 4.0;                                  // mm, radial\n                float ca = cos(c1.x), sa = sin(c1.x);\n                vec2 d = vec2(ca * dx + sa * dy, -sa * dx + ca * dy) / vec2(c0.z / c0.w, c0.z);   // ellipse: radial axis longer\n                float r = length(d);\n                float m = smoothstep(1.0, 1.0 - c1.z, r);\n                if (m > crypt) { crypt = m; cryptDepth = c1.y; }\n            }\n            crypt *= smoothstep(0.02, 0.08, v) * (1.0 - smoothstep(0.93, 0.98, v)) * fCrypt;\n            // the ABL and the stroma thin with depth: shallow dips stay lit, deep crypts go dark (fully at 60 µm of field)\n            float openHole = openMask * clamp((-spF - kOpen) / 0.06, 0.0, 1.0) * smoothstep(0.02, 0.08, v);\n\n            // ---- contraction furrows: explicit arcs (start/end turn, radius quadratic along the arc) ----\n            float furrow = 0.0;\n            for (int i = 0; i < 64; i++) {\n                if (i >= nFurrow) break;\n                vec4 f0 = OBJ(2 * i, 2), f1 = OBJ(2 * i + 1, 2);\n                float len = f0.y - f0.x;                                    // turns, > 0\n                float t = wrapDiff(u, f0.x); t = t < 0.0 ? t + 1.0 : t;      // 0..1 turns from the start\n                if (t > len) continue;\n                float tn = t / len;\n                float vk = f0.z + f0.w * tn + f1.x * tn * tn;\n                float ends = smoothstep(0.0, 0.12, tn) * (1.0 - smoothstep(0.88, 1.0, tn));\n                furrow = max(furrow, ends * f1.z * exp(-pow((v - vk) / f1.y, 2.0)) * fFurrow);\n            }\n\n            // ---- pigment spots and Wölfflin nodules: explicit ----\n            float spot = 0.0, spotMel = 0.0;\n            for (int i = 0; i < 64; i++) {\n                if (i >= nSpot) break;\n                vec4 p0 = OBJ(2 * i, 3), p1 = OBJ(2 * i + 1, 3);\n                float dx = wrapDiff(u, p0.x) * 6.2831853 * rMM(p0.y), dy = (v - p0.y) * 4.0;\n                float r = length(vec2(dx, dy)) / p0.z + 0.35 * (pfbm(uv + p1.y, 120.0, 30.0, s + 51.0) - 0.5);\n                float m = smoothstep(1.0, 0.55, r);\n                if (m > spot) { spot = m; spotMel = p0.w; }\n            }\n            float nodule = 0.0;\n            for (int i = 0; i < 128; i++) {\n                if (i >= nNodule) break;\n                vec4 n0 = OBJ(i, 4);\n                float dx = wrapDiff(u, n0.x) * 6.2831853 * rMM(n0.y), dy = (v - n0.y) * 4.0;\n                nodule = max(nodule, smoothstep(1.0, 0.4, length(vec2(dx, dy)) / n0.z));\n            }\n\n            // ---- ridge list (§19.3 C2): concentric ranges, each a dense (v, weight) table over u with a\n            // Gaussian profile of its own height / width / asymmetry; ridge 0 is the collarette\n            float ridgeH = 0.0;\n            int nRidge = int(OBJ(30, 0).x);\n            for (int i = 0; i < 16; i++) {\n                if (i >= nRidge) break;\n                float fu = fract(u) * 128.0; int i0 = int(fu); float t = fu - float(i0);\n                vec4 ra = OBJ(i0, 5 + i), rb = OBJ((i0 + 1) % 128, 5 + i), rh = OBJ(128, 5 + i);\n                float vr = mix(ra.x, rb.x, t), wr = mix(ra.y, rb.y, t);\n                float d = (v - vr) / max(rh.y, 0.005);\n                float k = d < 0.0 ? 1.0 + rh.z : 1.0 - rh.z;                       // asymmetry: inner slope vs outer\n                ridgeH += rh.x * wr * exp(-d * d * k);\n            }\n            // ---- height (mm) ----\n            float h = 0.0;\n            h += hLayers * 0.035 * g_fibreContrast * (0.6 + 0.4 * fBright);   // layered relief: top strands high, lower layers and the floor stepped down\n            h += ridgeH * fColl;\n            h -= cryptDepth * crypt;\n            h -= 0.035 * furrow * g_furrowDepth;\n            h -= 0.02 * radialF;\n            h += fHeight;\n            {   // splat field → height: bumps and smears as they are; openings deepened by g_openDepth (a −0.08 mm\n                // field is a 0.24 mm hole at 3×), walls from the field's own gradient — real slopes for the shading\n                float neg = max(0.0, -spF - kOpen);\n                h += max(spF, 0.0) - kOpen * smoothstep(0.0, kOpen, -spF) - g_openDepth * neg;\n            }\n            h += 0.05 * nodule;\n            h *= smoothstep(0.0, 0.03, v);                          // flat at the ruff\n\n            // ---- stroma density and melanin ----\n            float stroma = fStroma * mix(0.7, 1.0, cloud);          // strand material; the gap material is T2.ba, mixed by the ridge at shading\n            stroma *= mix(1.0, 0.06, crypt);                          // crypt floors: almost no scattering stroma left\n            stroma *= mix(1.0, 0.45, openHole);\n            stroma *= mix(1.0, 0.6, pupZone * 0.5);                   // thinner pupillary zone\n            stroma = mix(stroma, stroma * 0.3, smoothstep(1.0 - g_limbalWidth, 1.0, v) * g_limbalDark);\n            stroma += 0.6 * nodule;\n\n            float mel = fMelanin;\n            mel *= mix(1.0, 0.45, openHole);                          // milder than before: occlusion darkens the floor now\n            mel *= mix(1.0, g_pupZoneMel, pupZone);                   // denser ABL near the pupil\n            mel *= mix(1.0, 1.2, collMask);\n            mel += spotMel * spot;\n            mel += fMelanin * 1.5 * smoothstep(1.0 - g_limbalWidth, 1.0, v) * g_limbalDark + 0.6 * smoothstep(1.0 - g_limbalWidth, 1.0, v) * g_limbalDark;\n            mel *= mix(1.0, 0.08, crypt);                             // a crypt is a hole in the ABL (01 §3): the dark IPE shows\n\n            T0 = vec4(h, stroma, mel, max(crypt, 0.6 * openHole));    // .a drives the floor shadow in the photo shader\n            T1 = vec4(collMask, furrow, spot, ridge);                   // .a = strand coverage (the two-material mix)\n            T2 = vec4(fPheo, fYellow, fGapMel, fGapStroma);\n            T3 = vec4(clamp(occL, 0.0, 1.0), thickL, coarse, 1.0);\n        }\n    ",
"vs-bundle": "\n        #version 300 es\n        in vec2 a_pos;        // atlas uv, already offset across the ribbon\n        in float a_side;      // −1..1 across the ribbon\n        in vec2 a_bh;         // brightness, height (mm)\n        out float v_side; out vec2 v_bh;\n        void main() { v_side = a_side; v_bh = a_bh; gl_Position = vec4(a_pos * 2.0 - 1.0, 0.0, 1.0); }\n    ",
"fs-bundle": "\n        #version 300 es\n        precision highp float;\n        in float v_side; in vec2 v_bh;\n        out vec4 fragColor;\n        void main() {\n            float prof = pow(max(1.0 - abs(v_side), 0.0), 1.3);\n            fragColor = vec4(v_bh.x * prof, v_bh.y * prof, 0.0, 1.0);\n        }\n    ",
"vs-strand": "\n        #version 300 es\n        in vec2 a_pos;        // atlas uv, already offset across the ribbon (half width + an antialiasing margin)\n        in float a_side;      // signed distance across the ribbon, mm\n        in vec2 a_par;        // half width (mm), brightness\n        out float v_side; out vec2 v_par;\n        void main() { v_side = a_side; v_par = a_par; gl_Position = vec4(a_pos * 2.0 - 1.0, 0.0, 1.0); }\n    ",
"fs-strand": "\n        #version 300 es\n        precision highp float;\n        uniform float u_texelMM;\n        in float v_side; in vec2 v_par;\n        out vec4 fragColor;\n        void main() {\n            float d = abs(v_side), hw = v_par.x, e = max(0.3 * hw, u_texelMM);\n            float cov = 1.0 - smoothstep(hw - e, hw + e, d);\n            float tube = sqrt(max(0.0, 1.0 - (d * d) / (hw * hw)));\n            fragColor = vec4(cov, tube * cov, v_par.y * cov, 1.0);\n        }\n    ",
"vs-splat": "\n        #version 300 es\n        in vec2 a_pos;        // atlas uv of the quad corner\n        in vec2 a_local;      // corner offset from the centre, mm (tangential, radial)\n        in vec4 a_par;        // σa, σb (mm), θ (rad from the radial direction), amplitude (mm)\n        out vec2 v_local; out vec4 v_par;\n        void main() { v_local = a_local; v_par = a_par; gl_Position = vec4(a_pos * 2.0 - 1.0, 0.0, 1.0); }\n    ",
"fs-splat": "\n        #version 300 es\n        precision highp float;\n        in vec2 v_local; in vec4 v_par;\n        out vec4 fragColor;\n        void main() {\n            float c = cos(v_par.z), sn = sin(v_par.z);\n            float xa = c * v_local.x + sn * v_local.y, yb = -sn * v_local.x + c * v_local.y;\n            float g = exp(-0.5 * (xa * xa / (v_par.x * v_par.x) + yb * yb / (v_par.y * v_par.y)));\n            fragColor = vec4(v_par.w * g, 0.0, 0.0, 1.0);\n        }\n    ",
"vs-splat4": "\n        #version 300 es\n        in vec2 a_pos; in vec2 a_local; in vec4 a_par; in vec4 a_amp;\n        out vec2 v_local; out vec4 v_par; out vec4 v_amp;\n        void main() { v_local = a_local; v_par = a_par; v_amp = a_amp; gl_Position = vec4(a_pos * 2.0 - 1.0, 0.0, 1.0); }\n    ",
"fs-splat4": "\n        #version 300 es\n        precision highp float;\n        in vec2 v_local; in vec4 v_par; in vec4 v_amp;\n        out vec4 fragColor;\n        void main() {\n            float c = cos(v_par.z), sn = sin(v_par.z);\n            float xa = c * v_local.x + sn * v_local.y, yb = -sn * v_local.x + c * v_local.y;\n            float g = exp(-0.5 * (xa * xa / (v_par.x * v_par.x) + yb * yb / (v_par.y * v_par.y)));\n            fragColor = v_amp * g;\n        }\n    ",
"fs-post": "\n        #version 300 es\n        precision highp float;\n        out vec4 fragColor;\n        uniform sampler2D u_src;\n        uniform vec2 u_resolution;\n        uniform float u_ev, u_grain, u_tone, u_ca, u_bloom, u_ref, u_sat;\n        uniform vec4 u_view;         // the tile of the frame this pass shows (x, y, w, h): the aberration belongs to the FRAME, not the screen\n        uniform float u_caFrame;     // 1 with the layer model: the frame's aberration, measured on the photographs (u_ca 0); 0 = the legacy screen formula\n        uniform int u_frame;\n        float hash(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }\n        vec3 aces(vec3 x) { const float a = 2.51, b = 0.03, c = 2.43, d = 0.59, e = 0.14; return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0); }\n        void main() {\n            vec2 uv = gl_FragCoord.xy / u_resolution;\n            // lateral chromatic aberration, growing with the square of the radius in the camera's FRAME (2026-09-28: it was the screen's,\n            // so a zoomed view got the fringes of a frame's corners at its own edges): the displacement is computed in frame units and\n            // brought back to the tile's (÷ u_view.zw) — at the full view it is the old one, to within the pose's own offset\n            // (the legacy model keeps the screen's formula and its amount: the UI contract's fits see it, and it is not this change's to move)\n            vec2 cS = uv - 0.5, cF = (u_view.xy + uv * u_view.zw) - 0.5, c = u_caFrame > 0.5 ? cF : cS; c.x *= u_resolution.x / u_resolution.y;\n            vec2 dir = (u_ref > 0.5 ? 0.0 : u_ca) * c * dot(c, c) * 0.012 / (u_caFrame > 0.5 ? u_view.zw : vec2(1.0));\n            vec4 sG = texture(u_src, uv);\n            vec3 col = vec3(texture(u_src, uv + dir).r, sG.g, texture(u_src, uv - dir).b);\n            float alpha = sG.a;\n            // bloom / veiling glare around anything above white (the catchlight)\n            vec3 bl = vec3(0.0);\n            if (u_bloom > 0.0 && u_ref < 0.5) {\n                float w = 0.0;\n                for (int k = 0; k < 16; k++) {\n                    float an = float(k) * 0.3926991;\n                    vec2 o = vec2(cos(an), sin(an)) * vec2(u_resolution.y / u_resolution.x, 1.0);\n                    vec4 s1 = texture(u_src, uv + o * 0.012), s2 = texture(u_src, uv + o * 0.03);\n                    bl += max(s1.rgb - 1.0, 0.0) * 1.0 + max(s2.rgb - 1.0, 0.0) * 0.5; w += 1.5;\n                }\n                bl = bl / w * u_bloom;\n                col += bl; alpha = max(alpha, min(1.0, dot(bl, vec3(1.0)) * 2.0));\n            }\n            col *= exp2(u_ev);\n            { float lum = dot(col, vec3(0.2126, 0.7152, 0.0722)); col = max(vec3(0.0), lum + (col - lum) * u_sat); }   // processing chroma gain (a camera parameter, fitted like EV)\n            if (u_tone > 0.5) col = aces(col) / aces(vec3(1.0));   // white (1.0) stays white\n            col = clamp(col, 0.0, 1.0);\n            col = pow(col, vec3(1.0 / 2.2));\n            if (u_ref < 0.5 && u_grain > 0.0) {\n                float lum = dot(col, vec3(0.3, 0.59, 0.11));\n                col += (hash(gl_FragCoord.xy + float(u_frame) * 7.0) - 0.5) * u_grain * (0.35 + 0.65 * (1.0 - lum));\n            }\n            fragColor = vec4(mix(vec3(1.0), col, alpha), 1.0);\n        }\n    ",
"fs-blit": "\n        #version 300 es\n        precision highp float;\n        out vec4 fragColor;\n        uniform sampler2D u_tex;\n        uniform vec4 u_rect;      // x, y, w, h in pixels\n        uniform int u_channel;    // 0 height, 1 stroma, 2 melanin, 3 crypt, 4 rgb\n        void main() {\n            vec2 uv = (gl_FragCoord.xy - u_rect.xy) / u_rect.zw;\n            vec4 t = texture(u_tex, uv);\n            vec3 c;\n            if (u_channel == 0) c = vec3(clamp(t.r * 2.5 + 0.5, 0.0, 1.0));\n            else if (u_channel == 1) c = vec3(t.g);\n            else if (u_channel == 2) c = vec3(clamp(t.b * 0.5, 0.0, 1.0));\n            else if (u_channel == 3) c = vec3(t.a);\n            else c = t.rgb;\n            fragColor = vec4(c, 1.0);\n        }\n    ",
"fs-photo": "\n        #version 300 es\n        precision highp float;\n\n        out vec4 fragColor;\n\n        uniform vec2 u_resolution;\n        uniform float u_time;\n        uniform int u_frame;\n        uniform sampler2D u_accum;\n        uniform vec2 u_mouse;\n        uniform float u_zoom;        // camera distance from the apex, mm\n        uniform float u_isMobile;\n        uniform vec4 u_view;         // sub-rectangle of the image this pass renders (x, y, w, h), 0..1\n        uniform float u_fstop;       // lens aperture f-number (DOF)\n        uniform float u_capZoom;     // the photograph's own camera distance, mm (the eye's pose): the depth of field is that shot's at every zoom\n        uniform float u_focus;       // focus offset from the apparent iris plane, mm (+ = deeper)\n        uniform float u_ref;         // 1 = reference pose: no jitter, no DOF\n        uniform vec3 u_keyColor;     // key light colour relative to the camera's white balance\n        uniform float u_useRot;      // 1 = use u_rot instead of the mouse orbit (fitter / reference pose)\n        uniform vec2 u_rot;          // rotX (pitch), rotY (yaw), rad\n\n        uniform float u_pupil;       // pupil diameter, mm\n        uniform float u_lightAngle;  // azimuth, rad\n        uniform float u_lightElev;   // elevation above the view axis, rad\n        uniform float u_debug;       // 1 = mm grid overlay · 13 = alignment mask (pupil 0, iris 0.5, outside 1) · 14 = coordinate map (u, tissue v, inside) · 15 = height view (h mm, crypt, inside)\n        uniform float u_refract;     // 1 = physical indices, 0 = n = 1 everywhere (test)\n        uniform float u_specular;    // 1 = corneal reflection of the studio, 0 = none (isolated photos carry no catchlight)\n        uniform float u_edgeFade;    // 1 = the last 4.5 % of the limbus blends into the page (presentation), 0 = opaque to the edge (fit / comparison)\n        uniform float u_edgeFadeW;   // how much of the limbus radius the blend takes: the eye's measured edge width in mm over the limbus radius (study/11 §5.6), never the lens's\n        uniform float u_marchSteps;  // quality: parallax march steps (10 = normal)\n        uniform float u_shadowSteps; // quality: self-shadow march steps (7 = normal)\n\n        uniform float u_relief;      // height scale (1 = anatomical)\n\n        #define PI 3.14159265359\n\n        // ---- anatomy (mm) -------------------------------------------------\n        const float R_C   = 7.8;    // corneal apical radius\n        const float Q_C   = -0.26;  // asphericity\n        const float K_C   = 1.0 + Q_C;\n        const float CCT   = 0.54;   // central corneal thickness\n        const float R_CB  = 6.5;    // posterior corneal radius\n        // §28 K1: the visible aperture is a pose parameter, not a constant. Semi-axes in mm (anatomical rest 5.85 × 5.40)\n        // and the rotation of the first axis (rad, ccw, world y up). An isolated photo's cutout sets them (fit.js solvePose).\n        uniform vec3 u_limb;\n        const float ROOT_R = 6.0;   // iris root radius (hidden behind the limbus)\n        const float ROOT_Z = 4.2;   // iris root depth\n        const float MARG_Z = 3.5;   // pupil margin depth (0.7 anterior of the root)\n        const float BULGE  = 0.2;   // convex mid-bow\n        uniform vec2 u_pupilOff;    // pupil decentration, mm (anatomical rest: 0.25 nasal, 0.15 superior); a pose parameter the fitter corrects\n        #define PUPIL_OFF u_pupilOff\n        const float RUFF_W = 0.08;  // pigment frill width\n\n        float N_AIR = 1.0, N_COR = 1.376, N_AQ = 1.336;\n\n        const vec3 BG_COL = vec3(1.0);\n\n        // ---- utils (legacy noise, unchanged) -------------------------------\n        float hash(vec2 p) {\n            vec3 p3  = fract(vec3(p.xyx) * .1031);\n            p3 += dot(p3, p3.yzx + 33.33);\n            return fract((p3.x + p3.y) * p3.z);\n        }\n        float noise(vec2 p) {\n            vec2 i = floor(p); vec2 f = fract(p);\n            f = f * f * (3.0 - 2.0 * f);\n            return mix(mix(hash(i), hash(i + vec2(1,0)), f.x), mix(hash(i + vec2(0,1)), hash(i + vec2(1,1)), f.x), f.y);\n        }\n        vec2 hash2(vec2 p) {\n            p = vec2(dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)));\n            return -1.0 + 2.0*fract(sin(p)*43758.5453123);\n        }\n        float voronoi(in vec2 x) {\n            vec2 n = floor(x); vec2 f = fract(x); float m = 8.0;\n            for (int j=-1; j<=1; j++) for (int i=-1; i<=1; i++) {\n                vec2 g = vec2(float(i), float(j));\n                vec2 o = hash2(n + g);\n                vec2 r = g + o - f;\n                float d = dot(r,r);\n                if (d<m) m = d;\n            }\n            return sqrt(m);\n        }\n        float fbm(vec2 p) {\n            float v = 0.0; float a = 0.5;\n            for (int i = 0; i < 5; ++i) { v += a * noise(p); p = p * 2.0 + 100.0; a *= 0.5; }\n            return v;\n        }\n        float ridgedNoise(vec2 p) { return 2.0 * (0.5 - abs(0.5 - noise(p))); }\n\n        // ---- cornea front: conicoid  r^2 - 2 R z + K z^2 = 0 ----------------\n        float corneaSag(vec2 xy) {\n            float r2 = dot(xy, xy);\n            float s = sqrt(max(1.0 - K_C * r2 / (R_C*R_C), 0.0));\n            return (r2 / R_C) / (1.0 + s);\n        }\n        vec3 corneaNormal(vec3 p) {                 // outward (toward the camera)\n            return normalize(vec3(p.x, p.y, -R_C + K_C * p.z));\n        }\n        // nearest intersection of ray (o,d) with the front sheet; returns t or -1\n        float hitCorneaFront(vec3 o, vec3 d) {\n            float A = d.x*d.x + d.y*d.y + K_C*d.z*d.z;\n            float B = 2.0*(o.x*d.x + o.y*d.y) - 2.0*R_C*d.z + 2.0*K_C*o.z*d.z;\n            float C = o.x*o.x + o.y*o.y - 2.0*R_C*o.z + K_C*o.z*o.z;\n            float disc = B*B - 4.0*A*C;\n            if (disc < 0.0) return -1.0;\n            float sq = sqrt(disc);\n            float t0 = (-B - sq) / (2.0*A);\n            float t1 = (-B + sq) / (2.0*A);\n            // the front sheet is the one with the smaller z; try both in order\n            if (t0 > 0.0) { vec3 p = o + d*t0; if (p.z >= -0.001 && p.z < R_C/K_C) return t0; }\n            if (t1 > 0.0) { vec3 p = o + d*t1; if (p.z >= -0.001 && p.z < R_C/K_C) return t1; }\n            return -1.0;\n        }\n        // limbus ellipse test: <1 inside the cornea\n        float limbusNorm(vec2 xy) { float lc = cos(u_limb.z), ls = sin(u_limb.z); return length(vec2(lc * xy.x + ls * xy.y, lc * xy.y - ls * xy.x) / u_limb.xy); }\n\n        // ---- cornea back: sphere ----------------------------------------------\n        const vec3 CB_C = vec3(0.0, 0.0, CCT + R_CB);\n        float hitSphereNear(vec3 o, vec3 d, vec3 c, float R) {\n            vec3 oc = o - c;\n            float b = dot(oc, d);\n            float cc = dot(oc, oc) - R*R;\n            float disc = b*b - cc;\n            if (disc < 0.0) return -1.0;\n            float sq = sqrt(disc);\n            float t = -b - sq;\n            if (t < 0.0) t = -b + sq;\n            return t;\n        }\n\n        // ---- iris surface of revolution around the (decentred) pupil ------------\n        // tissue coordinate v: 0 at the pupil margin, 1 at the root\n        float rootRadiusFrom(vec2 c, vec2 u) {        // distance from pupil centre c along unit u to the root circle\n            float cu = dot(c, u);\n            return -cu + sqrt(max(cu*cu + ROOT_R*ROOT_R - dot(c,c), 0.0));\n        }\n        float irisZ(float v) {\n            float vv = clamp(v, 0.0, 1.0);\n            float v2 = pow(vv, 1.4);\n            float bump = 4.0 * v2 * (1.0 - v2);     // peaks at v ≈ 0.6\n            return mix(MARG_Z, ROOT_Z, vv) - BULGE * bump;\n        }\n        // polar/tissue coordinates of a point in the iris plane\n        void irisCoords(vec2 xy, float rp, out float r, out float v, out float ang, out float annulus) {\n            vec2 q = xy - PUPIL_OFF;\n            r = length(q);\n            vec2 u = r > 1e-5 ? q / r : vec2(1.0, 0.0);\n            ang = atan(q.y, q.x);\n            float rr = rootRadiusFrom(PUPIL_OFF, u);\n            annulus = rr - rp;\n            v = (r - rp) / annulus;\n        }\n        float irisSurfF(vec3 p, float rp) {         // >0 when p is behind the surface\n            float r, v, a, w; irisCoords(p.xy, rp, r, v, a, w);\n            return p.z - irisZ(v);\n        }\n        float hitIris(vec3 o, vec3 d, float rp) {\n            float t = 0.0, f0 = irisSurfF(o, rp);\n            if (f0 > 0.0) return 0.0;\n            float step = 0.3;\n            for (int i = 0; i < 40; i++) {\n                float tn = t + step;\n                float f = irisSurfF(o + d*tn, rp);\n                if (f > 0.0) {\n                    float a = t, b = tn;\n                    for (int k = 0; k < 10; k++) {\n                        float m = 0.5*(a+b);\n                        if (irisSurfF(o + d*m, rp) > 0.0) b = m; else a = m;\n                    }\n                    return 0.5*(a+b);\n                }\n                t = tn;\n                if (t > 12.0) break;\n            }\n            return -1.0;\n        }\n        vec3 irisGeomNormal(vec3 p, float rp) {     // toward the cornea (−z side)\n            vec2 e = vec2(0.01, 0.0);\n            float dx = irisSurfF(p + e.xyy, rp) - irisSurfF(p - e.xyy, rp);\n            float dy = irisSurfF(p + e.yxy, rp) - irisSurfF(p - e.yxy, rp);\n            float dz = irisSurfF(p + e.yyx, rp) - irisSurfF(p - e.yyx, rp);\n            return -normalize(vec3(dx, dy, dz));\n        }\n\n        // ---- baked atlas sampling ------------------------------------------------------\n        uniform sampler2D u_atlas0;   // height | stroma | melanin | crypt\n        uniform sampler2D u_atlas1;   // collarette | furrow | spot | nodule\n        uniform sampler2D u_atlas2;   // pheo | yellow | gap melanin | gap stroma\n        uniform sampler2D u_atlas3;   // occlusion | stroma thickness | top-layer coverage\n        uniform sampler2D u_f0;       // flow pack: strand direction for the anisotropic sheen\n        uniform sampler2D u_f1;       // flow pack: strand brightness (§19: reaches the shading directly)\n        uniform vec2  u_atlasSize;\n        uniform float u_rp0;          // pupil ratio the bake is referenced to\n        uniform float u_pheo;         // pheomelanin fraction\n        uniform float u_mie;          // neutral vs Rayleigh scatter\n        uniform float u_rayExp;       // rayleigh exponent (4..6)\n        uniform float u_melScale;     // multiplies the baked melanin\n        uniform float u_ringStrength; // central heterochromia: melanin added inside the ring\n        uniform float u_ringR;        // ring outer radius in tissue v\n        uniform float u_ringPheo;     // pheomelanin fraction inside the ring\n        uniform float u_ruffScallop;  // scallop amplitude of the pupillary ruff (rises with dilation)\n        uniform float u_stromaMax;    // the genome's stroma density (normalises the fibre proxy)\n        uniform float u_srcType;      // 0 disc (sun / bare flash), 1 softbox, 2 ring flash, 3 twin flash\n        uniform float u_srcSize;      // angular half-size of the source, rad\n        uniform float u_lid;          // upper lid edge, mm above the eye centre\n        uniform float u_ambient;      // room brightness relative to the key (0..1)\n\n        // ---- optics helpers ----------------------------------------------------------\n        float fresnel(float cosT, float n1, float n2) {\n            float r0 = (n1 - n2) / (n1 + n2); r0 *= r0;\n            return r0 + (1.0 - r0) * pow(1.0 - cosT, 5.0);\n        }\n        vec3 refractSafe(vec3 I, vec3 N, float eta) {\n            vec3 r = refract(I, N, eta);\n            return dot(r, r) < 1e-6 ? reflect(I, N) : r;\n        }\n\n        // ---- studio environment (04 §A) ---------------------------------------------------\n        // Radiometry: the key gives irradiance 1 on a surface facing it. A white Lambertian\n        // surface then has radiance 1/π; the display maps radiance × π, so white → 1.0.\n        float srcSolidAngle(float type, float sz) {\n            if (type < 0.5) return 2.0 * PI * (1.0 - cos(sz));\n            if (type < 1.5) return 4.0 * (1.4 * sz) * sz;\n            if (type < 2.5) return 2.0 * PI * (cos(0.6 * sz) - cos(sz));\n            return 2.0 * 2.0 * PI * (1.0 - cos(0.7 * sz));\n        }\n        // 1 where `dir` sees the source\n        float sourceMask(vec3 dir, vec3 L, vec3 camDir, float type, float sz) {\n            vec3 u = normalize(cross(L, abs(L.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0)));\n            vec3 v = cross(u, L);\n            float soft = 0.12 * sz;\n            if (type < 0.5) {                                  // disc\n                float ang = acos(clamp(dot(dir, L), -1.0, 1.0));\n                return 1.0 - smoothstep(sz - soft, sz + soft, ang);\n            } else if (type < 1.5) {                           // softbox, landscape rectangle\n                float dl = dot(dir, L); if (dl <= 0.0) return 0.0;\n                float au = atan(dot(dir, u), dl), av = atan(dot(dir, v), dl);\n                return (1.0 - smoothstep(1.4 * sz - soft, 1.4 * sz + soft, abs(au))) *\n                       (1.0 - smoothstep(sz - soft, sz + soft, abs(av)));\n            } else if (type < 2.5) {                           // ring flash around the lens\n                float ang = acos(clamp(dot(dir, camDir), -1.0, 1.0));\n                return smoothstep(0.6 * sz - soft, 0.6 * sz + soft, ang) * (1.0 - smoothstep(sz - soft, sz + soft, ang));\n            } else {                                           // twin flash, ±0.5 rad about the key\n                vec3 L1 = normalize(L * cos(0.5) + u * sin(0.5));\n                vec3 L2 = normalize(L * cos(0.5) - u * sin(0.5));\n                float a1 = acos(clamp(dot(dir, L1), -1.0, 1.0)), a2 = acos(clamp(dot(dir, L2), -1.0, 1.0));\n                float r = 0.7 * sz;\n                return max(1.0 - smoothstep(r - soft, r + soft, a1), 1.0 - smoothstep(r - soft, r + soft, a2));\n            }\n        }\n        // the upper lid blocks steep upward directions (and casts the band across the top of the eye)\n        float lidSky(vec3 dir) {\n            float thr = 0.15 + 0.12 * (u_lid - 3.0);\n            return 1.0 - 0.95 * smoothstep(thr - 0.12, thr + 0.12, dir.y);\n        }\n        vec3 envRadiance(vec3 dir, vec3 L, vec3 camDir) {\n            float Ls = 1.0 / max(srcSolidAngle(u_srcType, u_srcSize), 1e-4);\n            vec3 src = u_keyColor * Ls * sourceMask(dir, L, camDir, u_srcType, u_srcSize);\n            vec3 room = vec3(0.32 * u_ambient) * lidSky(dir) * (0.75 + 0.25 * dir.z * -1.0);\n            return src + room;\n        }\n        // where does the key light enter the cornea to reach iris point P? Refract with the normal\n        // above P, intersect, then refract again with the normal at the entry point (2 iterations\n        // converge; the one-shot version breaks on the far side, where the true entry is central).\n        bool lightEntry(vec3 P, vec3 L, float eta, out vec3 toLight, out vec3 E) {\n            vec3 n = corneaNormal(vec3(P.xy, corneaSag(P.xy)));\n            E = P; toLight = -L;\n            for (int i = 0; i < 3; i++) {\n                toLight = -refractSafe(-L, n, eta);\n                float t = hitCorneaFront(P, toLight);\n                if (t <= 0.0) return false;\n                E = P + toLight * t;\n                n = corneaNormal(E);\n            }\n            return true;\n        }\n        float lidBand(vec3 P) {   // shadow of the upper lid on the iris, seen through the cornea\n            return 1.0 - 0.65 * smoothstep(u_lid - 3.2, u_lid - 0.9, P.y);\n        }\n\n        // dilation remap (05 §4.1): tissue v from the live pupil ratio\n        float remapV(float vlin, float rp) {\n            float k = 1.0 + 0.35 * (rp - u_rp0);\n            return pow(clamp(vlin, 0.0, 1.0), k);\n        }\n        vec2 atlasUV(float ang, float v) { return vec2(ang / (2.0 * PI) + 0.5, v); }\n\n        // two-layer colour (02 §4) evaluated SPECTRALLY at load into a 3-D LUT (study/00 §16):\n        // axes = sqrt(melanin / 6), stroma·thickness / 0.5, pheomelanin (8 slices) × yellow absorber\n        // (4 slices, lerped by hand). Falls back to the analytic 3-band model when u_useLut = 0.\n        uniform highp sampler3D u_lut;\n        uniform float u_useLut;\n        uniform float u_yellow;       // yellow (lipofuscin / pheomelanic) absorber on the strands, 0..2.5\n        uniform float u_limbalMilk;   // scattering of the peripheral cornea over the limbus, 0..1\n        uniform float u_gapShadow;    // §22 F0: light reaching the gap floor between strands (0.55 v59, 0.8 v62)\n        vec3 irisAlbedoLut(float mel, float stroma, float thick, float pheo, float yellow) {\n            float x = sqrt(clamp(mel / 6.0, 0.0, 1.0));\n            float y = clamp(stroma * thick / 0.5, 0.0, 1.0);\n            float yl = clamp(yellow / 2.5, 0.0, 1.0) * 7.0;             // 0..7 across 8 yellow slices\n            float y0 = floor(yl), f = yl - y0; y0 = min(y0, 6.0);\n            float pz = clamp(pheo, 0.0, 1.0) * 7.0;                     // 0..7 across 8 pheo slices\n            // slice index z = yellowIdx * 8 + pheoIdx, sampled at texel centres (64 slices)\n            float z0 = (y0 * 8.0 + pz + 0.5) / 64.0, z1 = ((y0 + 1.0) * 8.0 + pz + 0.5) / 64.0;\n            vec3 a = texture(u_lut, vec3(x, y, z0)).rgb, b = texture(u_lut, vec3(x, y, z1)).rgb;\n            return mix(a, b, f);\n        }\n        vec3 irisAlbedoAnalytic(float mel, float stroma, float thick, float pheo) {\n            const vec3 lam = vec3(611.0, 549.0, 464.0) / 550.0;\n            vec3 a_eu = pow(lam, vec3(-3.33));\n            vec3 a_ph = pow(lam, vec3(-4.75));\n            vec3 ray  = pow(1.0 / lam, vec3(u_rayExp));\n            const vec3 R_ipe  = vec3(0.045, 0.030, 0.020);\n            const vec3 rho_eu = vec3(0.065, 0.038, 0.022);\n            const vec3 rho_ph = vec3(0.26, 0.15, 0.055);\n            vec3 melS = mix(a_eu, a_ph, pheo);\n            float Ma = mel, Ms = 0.7 * mel;\n            vec3 sig_s = max(stroma, 0.005) * mix(ray, vec3(1.0), u_mie);\n            vec3 sig_a = Ms * melS + 1e-4;\n            vec3 a = 1.0 + sig_a / sig_s;\n            vec3 b = sqrt(max(a * a - 1.0, 1e-6));\n            vec3 x = min(b * sig_s * thick, vec3(30.0));   // optical thickness at the chapter's scale (calibrated: blue → 115,124,145)\n            vec3 coth = cosh(x) / sinh(x);\n            vec3 Rs = (1.0 - R_ipe * (a - b * coth)) / (a - R_ipe + b * coth);\n            vec3 T = exp(-Ma * melS);\n            vec3 rho = mix(rho_eu, rho_ph, pheo);\n            return (1.0 - T) * rho + T * T * Rs;\n        }\n        vec3 irisAlbedo(float mel, float stroma, float thick, float pheo) {\n            return u_useLut > 0.5 ? irisAlbedoLut(mel, stroma, thick, pheo, u_yellow) : irisAlbedoAnalytic(mel, stroma, thick, pheo);\n        }\n\n\n        // grid overlay in mm around the pupil centre\n        float gridLine(float x, float period, float w) {\n            float f = abs(fract(x / period + 0.5) - 0.5) * period;\n            return 1.0 - smoothstep(0.0, w, f);\n        }\n\n        // ---- shading of one refracted ray -------------------------------------------------\n        vec3 shadeInterior(vec3 pIn, vec3 dIn, vec3 nFront, vec3 dView, vec3 L, float rp, bool hq) {\n            float t = hitIris(pIn, dIn, rp);\n            if (t < 0.0) return vec3(0.0);\n            vec3 P = pIn + dIn * t;\n            float r, v, a, w; irisCoords(P.xy, rp, r, v, a, w);\n            bool maskView = u_debug > 12.5 && u_debug < 13.5, mapView = u_debug > 13.5 && u_debug < 14.5, hView = u_debug > 14.5 && u_debug < 15.5;\n            if (v < 0.0) return (maskView || mapView || hView) ? vec3(0.0) : vec3(0.0015, 0.0012, 0.001);\n            if (maskView) return vec3(0.5);                       // alignment mask: the iris, unshaded\n\n            float rpr = rp / ROOT_R;\n            float vt = remapV(v, rpr);\n            vec2 uv = atlasUV(a, vt);\n            if (mapView) return vec3(uv, 1.0);                    // coordinate map: field (u, tissue v) of this pixel, through the same refraction\n\n            // texel footprint in mm → explicit lod. Analytic, not from screen derivatives: the lens\n            // sample and the sub-pixel jitter differ per pixel, which would inflate fwidth() and\n            // pull in blurry mips. Pixel angle × distance, over the corneal magnification.\n            float mmPerPx = (24.0 * u_view.w / u_resolution.y) / 100.0 * (u_zoom + 3.5) / 1.1;\n            float texU = 2.0 * PI * max(r, 0.3) / u_atlasSize.x;   // mm per texel, angular\n            float texV = w / u_atlasSize.y;                         // mm per texel, radial\n            float lod = clamp(log2(mmPerPx / min(texU, texV)), 0.0, 6.0);\n\n            // parallax march against the baked height: the true surface is z_geom(v) − h, with h toward\n            // the camera. Start above the highest relief and step until the ray is under the surface.\n            const float H_MAX = 0.16, H_MIN = -0.32;\n            float tStart = -(H_MAX) / max(dIn.z, 0.15), tEnd = -(H_MIN) / max(dIn.z, 0.15);\n            float tA = tStart, tB = tEnd;\n            int nM = int(u_marchSteps + 0.5);\n            float dt = (tEnd - tStart) / float(nM);\n            vec3 Pp = P; float rr, vv, aa, ww;\n            for (int i = 1; i <= 24; i++) {\n                if (i > nM) break;\n                float tt = tStart + dt * float(i);\n                Pp = P + dIn * tt;\n                irisCoords(Pp.xy, rp, rr, vv, aa, ww);\n                float hh = textureLod(u_atlas0, atlasUV(aa, remapV(vv, rpr)), lod).r * u_relief;\n                if (Pp.z > irisZ(vv) - hh) { tB = tt; break; }\n                tA = tt;\n            }\n            for (int k = 0; k < 4; k++) {\n                float tm = 0.5 * (tA + tB);\n                Pp = P + dIn * tm;\n                irisCoords(Pp.xy, rp, rr, vv, aa, ww);\n                float hh = textureLod(u_atlas0, atlasUV(aa, remapV(vv, rpr)), lod).r * u_relief;\n                if (Pp.z > irisZ(vv) - hh) tB = tm; else tA = tm;\n            }\n            Pp = P + dIn * (0.5 * (tA + tB));\n            irisCoords(Pp.xy, rp, r, v, a, w);\n            if (v < 0.0) return vec3(0.0015, 0.0012, 0.001);\n            vt = remapV(v, rpr); uv = atlasUV(a, vt);\n            vec4 t0 = textureLod(u_atlas0, uv, lod);\n            vec4 t1 = textureLod(u_atlas1, uv, lod);\n            vec4 t2 = textureLod(u_atlas2, uv, lod);\n            vec4 t3 = textureLod(u_atlas3, uv, lod);   // occlusion | stroma thickness\n            float occ = t3.r;\n            float h = t0.r * u_relief;\n            if (hView) return vec3(h, t0.a, 1.0);                   // height view: baked relief (mm) and crypt mask, for the HEIGHT A/B\n\n            // dilation modulates the folds (05 §4.1)\n            float dil = smoothstep(0.35, 0.65, rpr);\n            float furrow = t1.g * mix(0.4, 1.3, dil);\n            float crypt = t0.a * mix(1.15, 0.85, dil);\n\n            // normal from height differences, in mm\n            vec2 du = vec2(1.0 / u_atlasSize.x, 0.0), dv = vec2(0.0, 1.0 / u_atlasSize.y);\n            float hR = textureLod(u_atlas0, uv + dv, lod).r * u_relief - textureLod(u_atlas0, uv - dv, lod).r * u_relief;\n            float hT = textureLod(u_atlas0, uv + du, lod).r * u_relief - textureLod(u_atlas0, uv - du, lod).r * u_relief;\n            float dvdr = (1.0 / w) * (vt > 0.0 ? (1.0 + 0.35 * (rpr - u_rp0)) * pow(max(v, 1e-3), 0.35 * (rpr - u_rp0)) : 1.0);\n            float slopeR = hR / (2.0 * texV) * (w * dvdr);         // dh/dr per mm\n            float slopeT = hT / (2.0 * texU);                        // dh/dtangent per mm\n            vec3 Ng = irisGeomNormal(P, rp);\n            vec2 rad = normalize((P.xy - PUPIL_OFF) + 1e-6);\n            vec3 radial = vec3(rad, 0.0), tangent = vec3(-rad.y, rad.x, 0.0);\n            // height is positive toward the camera (−z), so a rising slope tilts the normal against it\n            vec3 N = normalize(Ng + (slopeR * radial + slopeT * tangent));\n\n            // light path: refract the key at the cornea above the point, find its entry point, and\n            // measure how the entry footprint maps onto the iris (the corneal caustic, 01 §2)\n            float etaL = u_refract > 0.5 ? N_AIR / N_AQ : 1.0;\n            vec3 toLight, E0;\n            bool entered = lightEntry(P, L, etaL, toLight, E0);\n            float exitR = entered ? limbusNorm(E0.xy) : 2.0;\n            float limbShadow = 1.0 - smoothstep(0.97, 1.03, exitR);\n            float causticGain = 1.0, Fentry = 0.02, dbgArea = 0.0, dbgCos = 0.0;\n            if (entered) {\n                const float dd = 0.05;\n                vec3 tl1, tl2, E1, E2;\n                bool ok1 = lightEntry(P + vec3(dd, 0.0, 0.0), L, etaL, tl1, E1);\n                bool ok2 = lightEntry(P + vec3(0.0, dd, 0.0), L, etaL, tl2, E2);\n                if (ok1 && ok2) {\n                    float areaC = length(cross(E1 - E0, E2 - E0)) / (dd * dd);\n                    vec3 nE = corneaNormal(E0);\n                    float cosC = clamp(dot(nE, L), 0.0, 1.0);\n                    Fentry = fresnel(cosC, N_AIR, N_COR);\n                    causticGain = clamp(cosC * areaC / max(abs(toLight.z), 0.2), 0.0, 3.0);\n                    dbgArea = areaC; dbgCos = cosC;\n                }\n            }\n            float lid = lidBand(P);\n\n            // material\n            float mel = t0.b * u_melScale;\n            float stroma = t0.g;\n            float thick = mix(0.6, 1.0, smoothstep(0.0, 0.35, vt)) * (1.0 - 0.5 * furrow) * (0.5 + 0.6 * t3.g);   // §21 E1: the stroma thickness field\n            // central heterochromia (02 §3.1): a melanin ring around the pupil whose edge runs out\n            // along the fibre bundles (bright stroma = a bundle), pheomelanic like the hazel/amber middle\n            float fibreProxy = clamp(stroma / max(u_stromaMax, 1e-3), 0.0, 1.0);\n            float ringEdge = u_ringR * (0.7 + 0.6 * fibreProxy);\n            float ring = (1.0 - smoothstep(ringEdge - 0.08, ringEdge + 0.06, vt)) * (1.0 - crypt);\n            mel += u_ringStrength * ring;\n            float pheo = mix(t2.r, u_ringPheo, ring * clamp(u_ringStrength, 0.0, 1.0));\n            // two materials (06, 07 §2): strand = bright scattering collagen carrying the pigment,\n            // gap = the dark ground between strands; the baked ridge coverage mixes them\n            float ridge = t1.a;\n            vec3 albS = u_useLut > 0.5 ? irisAlbedoLut(mel, stroma, thick, pheo, t2.g) : irisAlbedoAnalytic(mel, stroma, thick, pheo);\n            vec3 albG = u_useLut > 0.5 ? irisAlbedoLut(t2.b + u_ringStrength * ring, t2.a, thick, pheo, t2.g * 0.85) : irisAlbedoAnalytic(t2.b, t2.a, thick, pheo);\n            vec3 col = mix(albG, albS, ridge);\n            col *= mix(u_gapShadow, 1.0, ridge);                      // contact shadow in the gaps, fitted (§22 F0)\n            col *= mix(1.0, 0.55, crypt);                            // crypt floor in shadow\n            col *= mix(1.0, 0.7, furrow);\n            col *= clamp(mix(0.0, 2.0, texture(u_f1, uv).b), 0.4, 1.6);   // the brightness field, not through the strand integration\n\n            // pupillary ruff\n            float scallop = 1.0 + u_ruffScallop * (0.6 * sin(a * 70.0) + 0.4 * sin(a * 23.0 + 1.7));\n            float ruff = 1.0 - smoothstep(RUFF_W * 0.6 * scallop, RUFF_W * 1.4 * scallop, (r - rp));\n            col = mix(col, vec3(0.045, 0.035, 0.028) * 1.5, ruff);\n\n            float diff = clamp(dot(N, toLight), 0.0, 1.0);\n            // self-shadowing along the refracted light: march the height field toward the source\n            float selfShadow = 0.0;\n            {\n                float tt = 0.02; int nS = int(u_shadowSteps + 0.5);\n                for (int i = 0; i < 16; i++) {\n                    if (i >= nS) break;\n                    vec3 Q = Pp + toLight * tt;\n                    float qr, qv, qa, qw; irisCoords(Q.xy, rp, qr, qv, qa, qw);\n                    float qh = textureLod(u_atlas0, atlasUV(qa, remapV(qv, rpr)), lod).r * u_relief;\n                    float surf = irisZ(qv) - qh;\n                    float pen = (Q.z - surf) - 0.006;             // >0: the ray is under the surface (bias vs acne)\n                    selfShadow = max(selfShadow, smoothstep(0.0, 0.02, pen) * (1.0 - float(i) / (float(nS) + 3.0)));\n                    tt *= pow(1.5, 7.0 / float(nS));   // the same reach whatever the step count\n                }\n            }\n            if (u_debug > 1.5 && u_debug < 2.5) return vec3(limbShadow);\n            if (u_debug > 2.5 && u_debug < 3.5) return vec3(clamp(dot(Ng, toLight), 0.0, 1.0));\n            if (u_debug > 3.5 && u_debug < 4.5) return vec3(exitR * 0.5);\n            if (u_debug > 4.5 && u_debug < 5.5) return vec3(clamp(h * 2.5 + 0.5, 0.0, 1.0));\n            if (u_debug > 5.5 && u_debug < 6.5) return vec3(stroma, mel * 0.5, crypt);\n            float wrap = clamp(dot(Ng, toLight) * 0.5 + 0.5, 0.0, 1.0);\n            float keyE = diff * causticGain * (1.0 - Fentry) * limbShadow * (1.0 - 0.9 * selfShadow) * lid * (0.55 + 0.45 * occ);   // lower strands and floors are shadowed by the layers above\n            float ambE = 0.5 * u_ambient * (1.0 - 0.6 * crypt) * (0.35 + 0.65 * lid) * (0.7 + 0.3 * wrap) * occ;\n            if (u_debug > 6.5 && u_debug < 7.5) return vec3(selfShadow);\n            if (u_debug > 7.5 && u_debug < 8.5) return vec3(causticGain * 0.5);\n            if (u_debug > 8.5 && u_debug < 9.5) return vec3(keyE);\n            if (u_debug > 9.5 && u_debug < 10.5) return vec3(dbgArea * 0.5);\n            if (u_debug > 10.5 && u_debug < 11.5) return vec3(dbgCos);\n            if (u_debug > 11.5 && u_debug < 12.5) return vec3(abs(toLight.z));\n            vec3 lit = col * (keyE + ambE);\n            lit += col * 0.08 * wrap * lid;                            // stroma translucency\n            vec3 hv = normalize(toLight - dIn);\n            lit += 0.05 * pow(clamp(dot(N, hv), 0.0, 1.0), 24.0);\n            // anisotropic sheen along the strands (wet collagen): Kajiya–Kay with the flow tangent\n            {\n                float th = mix(-1.05, 1.05, texture(u_f0, uv).r);\n                vec3 T = normalize(cos(th) * radial + sin(th) * tangent);\n                float sinTH = sqrt(max(0.0, 1.0 - pow(dot(T, hv), 2.0)));\n                lit += 0.12 * ridge * pow(sinTH, 48.0) * keyE;\n            }\n\n            if (u_debug > 0.5 && u_debug < 1.5) {\n                float g = gridLine(r, 1.0, 0.03);\n                float s = gridLine(a * 180.0 / PI, 30.0, 0.5);\n                lit = mix(lit, vec3(0.0, 1.0, 1.0), 0.7 * max(g, s));\n                float col1 = 1.0 - smoothstep(0.0, 0.05, abs(r - (rp + 1.5)));\n                lit = mix(lit, vec3(1.0, 0.0, 1.0), col1);\n                float rootL = 1.0 - smoothstep(0.0, 0.05, abs(v - 1.0) * w);\n                lit = mix(lit, vec3(1.0, 1.0, 0.0), rootL);\n            }\n            return lit;\n        }\n\n        // returns linear radiance × π in rgb; alpha = 1 on the cornea, 0 on the sclera / page\n        vec4 renderPass(vec3 ro, vec3 rd, vec3 L, bool insideCrop, float rp) {   // ro: camera, for the ring flash\n            float tC = hitCorneaFront(ro, rd);\n            if (tC < 0.0) {\n                // A ray that misses the cornea has no tissue behind it. Returning BG_COL (pure white)\n                // here made the debug views report the page as iris: getMap reads `inside` from the blue\n                // channel and v from the green, so every background pixel came back as inside at v ≈ 1.0\n                // — 60 % of the frame on ref 35 — and every polar unwrap splatted the background into the\n                // outermost rows and then filled inward from it. Mask / map / height views must say \"no data\".\n                if (u_debug > 12.5 && u_debug < 13.5) return vec4(1.0, 1.0, 1.0, 0.0);   // 13: outside the iris\n                if (u_debug > 13.5 && u_debug < 15.5) return vec4(0.0);                   // 14 map, 15 height: unsampled\n                return vec4(BG_COL, 0.0);\n            }\n            vec3 P = ro + rd * tC;\n            float ln = limbusNorm(P.xy);\n            bool maskView = u_debug > 12.5 && u_debug < 13.5, mapView = u_debug > 13.5 && u_debug < 15.5;   // 14 = coordinate map, 15 = height view: both raw\n            // presentation (edgeFade 1): the limbus blend is centred near the limbus, reaching a third of its width past it — the iris\n            // runs on behind the limbus to its root (ROOT_R 6 mm), and the photographs' own edge lies there (study/11 §5.6, eye 26: the\n            // blend ending AT the limbus put the render's edge 40 µm inward of the photo's). Fit, comparison and the maps: ln 1 as before.\n            float lnOut = (maskView || mapView) ? 1.0 : 1.0 + 0.35 * u_edgeFadeW * u_edgeFade;\n            if (ln > lnOut || (mapView && ln > 0.99)) {                  // the map stops 1 % short of the limbus: a ragged silhouette lets no background in\n                if (maskView) return vec4(1.0, 1.0, 1.0, 0.0);\n                if (mapView) return vec4(0.0);\n                // sclera: pure white, indistinguishable from the page\n                if (u_debug > 0.5) {\n                    float ring = 1.0 - smoothstep(0.0, 0.01, abs(ln - 1.0));\n                    return vec4(mix(BG_COL, vec3(1.0, 0.6, 0.0), ring), ring);\n                }\n                return vec4(BG_COL, 0.0);\n            }\n            vec3 nF = corneaNormal(P);\n            float cosT = clamp(dot(-rd, nF), 0.0, 1.0);\n            float F = u_refract > 0.5 ? fresnel(cosT, N_AIR, N_COR) : 0.0;\n\n            // refract air -> cornea -> aqueous\n            float eta1 = u_refract > 0.5 ? N_AIR / N_COR : 1.0;\n            float eta2 = u_refract > 0.5 ? N_COR / N_AQ : 1.0;\n            vec3 d1 = refractSafe(rd, nF, eta1);\n            float tB = hitSphereNear(P, d1, CB_C, R_CB);\n            vec3 P2 = P; vec3 d2 = d1;\n            if (tB > 0.0) {\n                P2 = P + d1 * tB;\n                vec3 nB = normalize(P2 - CB_C);      // sphere outward normal: faces the incoming ray (−z at the pole)\n                d2 = refractSafe(d1, nB, eta2);\n            }\n\n            vec3 iris = shadeInterior(P2, d2, nF, rd, L, rp, insideCrop);\n            if (maskView || mapView) return vec4(iris, 1.0);\n            vec3 col = iris * (1.0 - F);\n\n            // corneal reflection: the tear film mirrors the studio (source shape + room + lid)\n            vec3 refl = reflect(rd, nF);\n            vec3 camDir = normalize(ro - P);\n            col += u_specular * F * PI * envRadiance(refl, L, camDir);\n\n            // limbus (01 §3): the peripheral cornea is thicker and scatters, so the last ~0.5 mm goes\n            // milky before the opaque sclera takes over; the dark ring itself comes from the baked\n            // peripheral pigment plus the grazing-angle Fresnel loss above\n            float milky = smoothstep(0.90, 1.0, ln);\n            col = mix(col, mix(col, vec3(0.75, 0.72, 0.70), 0.5), milky * u_limbalMilk);\n            float edge = smoothstep(lnOut - u_edgeFadeW, lnOut, ln) * u_edgeFade;\n            if (u_debug > 0.5 && !maskView && !mapView) {\n                float ring = 1.0 - smoothstep(0.0, 0.01, abs(ln - 1.0));\n                col = mix(col, vec3(1.0, 0.6, 0.0), ring);\n            }\n            return vec4(col, 1.0 - edge);\n        }\n\n        void main() {\n            bool hq = u_ref < 0.5;                       // interactive/accumulated: stochastic sampling\n            float fr = float(u_frame);\n            vec2 jitter = hq ? vec2(hash(gl_FragCoord.xy + fr * 1.618), hash(gl_FragCoord.yx + fr * 2.718)) - 0.5 : vec2(0.0);\n            // image-space coordinate: u_view selects a tile of the full image (tiled capture)\n            vec2 img = u_view.xy + (gl_FragCoord.xy + jitter) / u_resolution * u_view.zw;   // 0..1\n            float aspect = u_resolution.x / u_resolution.y;\n            vec2 sensor = (img - 0.5) * vec2(aspect, 1.0) * 24.0;                            // mm on a 24 mm-tall sensor\n\n            // CAMERA: 100 mm lens at u_zoom mm from the apex, focused on the iris plane\n            float focal = 100.0;\n            // the eye turns toward the cursor: cursor right → eye rotates right (camera orbits left)\n            float rotX = u_useRot > 0.5 ? u_rot.x : (0.5 - u_mouse.y / u_resolution.y) * 0.75;\n            float rotY = u_useRot > 0.5 ? u_rot.y : (u_mouse.x / u_resolution.x - 0.5) * 1.0;\n            mat2 ry = mat2(cos(rotY), sin(rotY), -sin(rotY), cos(rotY));\n            mat2 rx = mat2(cos(rotX), sin(rotX), -sin(rotX), cos(rotX));\n\n            vec3 rd = normalize(vec3(sensor, focal));\n            vec3 ro = vec3(0.0);\n            // thin-lens depth of field: sample the aperture, aim at the focal point on the iris plane\n            if (hq && u_fstop < 64.0) {\n                // zoom is a CROP of one photograph (iori, 2026-09-28): the blur on the tissue (aperture × Δdepth / distance) stays\n                // the shot's, so the aperture scales with the distance — dollying in no longer blurs the whole iris\n                float lensR = 0.5 * focal / u_fstop * (u_zoom + 3.05 + u_focus) / max(u_capZoom + 3.05 + u_focus, 1.0);   // mm\n                float h1 = hash(gl_FragCoord.xy * 0.37 + fr * 3.1), h2 = hash(gl_FragCoord.yx * 0.71 + fr * 5.3);\n                vec2 lens = lensR * sqrt(h1) * vec2(cos(6.2831853 * h2), sin(6.2831853 * h2));\n                float focusDist = u_zoom + 3.05 + u_focus;   // the apparent (refracted) iris plane, 01 §2\n                vec3 pf = rd * (focusDist / rd.z);\n                ro = vec3(lens, 0.0);\n                rd = normalize(pf - ro);\n            }\n            // the eye is pivoted about its centre of rotation (~13 mm behind the apex)\n            vec3 pivot = vec3(0.0, 0.0, 13.0);\n            ro += vec3(0.0, 0.0, -u_zoom);\n            ro -= pivot; ro.yz *= rx; ro.xz *= ry; ro += pivot;\n            rd.yz *= rx; rd.xz *= ry;\n\n            float la = u_lightAngle, le = u_lightElev;\n            vec3 L = normalize(vec3(cos(la) * cos(le), sin(la) * cos(le), -sin(le)));   // toward the light\n            L.yz *= rx; L.xz *= ry;                                                      // light rig follows the camera\n\n            float rp = 0.5 * u_pupil;\n            vec4 col = renderPass(ro, rd, L, hq, rp);\n\n            if (u_frame > 0 && hq) {\n                vec4 prev = texture(u_accum, gl_FragCoord.xy / u_resolution.xy);\n                col = mix(prev, col, 1.0 / (fr + 1.0));\n            }\n            fragColor = col;                              // linear radiance × π, alpha = cornea coverage\n        }\n    "
};
